def transform(g):
    g=[row[:] for row in g]
    ks=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j]==8]
    top=min(p[0] for p in ks); left=min(p[1] for p in ks)
    fh=max(p[0] for p in ks)-top+1; fw=max(p[1] for p in ks)-left+1
    kc=[(i,j) for i in range(len(g)) for j in range(len(g[0])) if g[i][j] not in (0,8)]
    kt=min(p[0] for p in kc); kl=min(p[1] for p in kc)
    kh=max(p[0] for p in kc)-kt+1; kw=max(p[1] for p in kc)-kl+1
    n=len(kc); total=len(ks)
    s=int(round((total/n)**0.5))
    assert s*s*n==total and fh==kw*s and fw==kh*s, (s,total,n,fh,fw,kh,kw)
    rot=[[g[kt+kh-1-c][kl+r] if g[kt+kh-1-c][kl+r] not in (0,8) else 0 for c in range(kh)] for r in range(kw)]
    out=[row[:] for row in g]
    for r in range(kw):
        for c in range(kh):
            if rot[r][c]:
                for dr in range(s):
                    for dc in range(s):
                        out[top+r*s+dr][left+c*s+dc]=rot[r][c]
    return out
